{
  "story": "Why does KV caching speed up inference? Start with a shared prompt, then advance Uncached K/V and Cached K/V through decoding. Compare rebuilding history with reusing the KV cache. The Newest query still reads every context position, and both paths produce the same Next token.",
  "aha": {
    "stateId": "decode-e",
    "observation": "Cached K/V avoids rebuilding history, while the Newest query still reads every position and both paths produce the same Next token."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "decode-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell and algorithm/collection composition. Keep progress on this rail. Above the experiment, show: Use Previous or Next to compare decoding passes.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "kv-comparison",
      "kind": "fixed-picture",
      "presentation": "Place fixed assumptions above matched Uncached K/V and Cached K/V rows. Align corresponding token positions on a shared categorical scale. Select each region's phase using the state index; values remain fixed. Highlight only active regions. Reference captures show decode-e. Never animate or automatically advance.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "mechanism-callout",
      "kind": "active-callout",
      "presentation": "Place the explanation above the experiment, anchored to the named target. Identify the mechanism without duplicating numerical readouts.",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "work-and-status",
      "kind": "value-readout",
      "presentation": "Stack labeled readouts below the picture. Display exact integer counts without rounding. Each measurement appears here only. Render the final entry as the bound status line.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Decoding state",
      "presentation": "Navigation budget: one index control and Reset. Parameter-control budget: zero. Default index 0; bounds 0 through 2; increment 1. Use Previous and Next, retaining their names when disabled at boundaries. Support Left/Right arrows, keyboard activation, accessible names, and visible focus. Every state persists until learner action, including decode-e."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore index 0 and all fixed defaults. Support Enter and Space, an accessible name, and visible keyboard focus."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Shared prefill followed by two decoding passes",
        "regions": [
          {
            "id": "fixed-assumptions",
            "label": "Fixed assumptions",
            "values": [
              "K = key; V = value; q = newest query.",
              "Batch one; one head; one layer; causal attention; identical arithmetic; no eviction.",
              "Counts measure projected K/V vectors, excluding queries, attention arithmetic, and other transformer work."
            ]
          },
          {
            "id": "token-stream",
            "label": "Fixed token stream",
            "values": [
              "Prompt: A B C",
              "Assumed greedy continuation: D E F",
              "Each pass consumes the previous prediction and predicts the following token."
            ]
          },
          {
            "id": "uncached-kv",
            "label": "Uncached K/V",
            "phases": [
              "Build (K_A,V_A), (K_B,V_B), (K_C,V_C).",
              "Rebuild A–C; build (K_D,V_D).",
              "Rebuild A–D; build (K_E,V_E)."
            ]
          },
          {
            "id": "cached-kv",
            "label": "Cached K/V",
            "phases": [
              "Build (K_A,V_A), (K_B,V_B), (K_C,V_C).",
              "Reuse A–C; build only (K_D,V_D).",
              "Reuse A–D; build only (K_E,V_E)."
            ]
          },
          {
            "id": "kv-cache",
            "label": "KV cache",
            "phases": [
              "Store (K_A,V_A), (K_B,V_B), (K_C,V_C).",
              "Retain A–C; append (K_D,V_D).",
              "Retain A–D; append (K_E,V_E)."
            ]
          },
          {
            "id": "newest-query",
            "label": "Newest query",
            "phases": [
              "Both paths: q_C scores K_A…K_C and combines V_A…V_C.",
              "Both paths: q_D scores K_A…K_D and combines V_A…V_D.",
              "Both paths: q_E scores K_A…K_E and combines V_A…V_E."
            ]
          },
          {
            "id": "next-token",
            "label": "Next token",
            "phases": [
              "Both paths predict D.",
              "Both paths predict E.",
              "Both paths predict F."
            ]
          }
        ],
        "links": [
          {
            "from": "cached-kv",
            "to": "kv-cache",
            "label": "Append newly computed K/V"
          },
          {
            "from": "kv-cache",
            "to": "cached-kv",
            "label": "Reuse retained K/V on later passes"
          },
          {
            "from": "uncached-kv",
            "to": "newest-query",
            "label": "Recomputed history"
          },
          {
            "from": "kv-cache",
            "to": "newest-query",
            "label": "Retained history"
          },
          {
            "from": "newest-query",
            "to": "next-token",
            "label": "Same attention inputs and downstream computation"
          }
        ],
        "states": [
          {
            "id": "prefill",
            "label": "Prefill A–C",
            "short": "Shared initial work",
            "sentence": "Uncached K/V and Cached K/V build the prompt identically; the KV cache retains the cached path's results.",
            "why": "Both paths compute one key and one value per prompt token. The picture shows only the newest query, not every prefill query.",
            "active": [
              "kv-cache"
            ],
            "calloutRegion": "kv-cache",
            "readouts": [
              {
                "id": "pass-work",
                "label": "K/V vectors this pass · Uncached / Cached",
                "value": "6 / 6"
              },
              {
                "id": "attention-positions",
                "label": "Positions read by Newest query · both paths",
                "value": "3"
              },
              {
                "id": "cache-size",
                "label": "KV cache retained · vectors",
                "value": "6"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Shared prefill complete; retained history is ready for reuse."
              }
            ]
          },
          {
            "id": "decode-d",
            "label": "Decode D",
            "short": "First reuse",
            "sentence": "Cached K/V reuses the prompt entries and appends D; Uncached K/V rebuilds the entire prefix.",
            "why": "Previously computed keys and values cannot change under causal attention. The Newest query still uses every available key and value.",
            "active": [
              "cached-kv",
              "kv-cache"
            ],
            "calloutRegion": "cached-kv",
            "readouts": [
              {
                "id": "pass-work",
                "label": "K/V vectors this pass · Uncached / Cached",
                "value": "8 / 2"
              },
              {
                "id": "attention-positions",
                "label": "Positions read by Newest query · both paths",
                "value": "4"
              },
              {
                "id": "cache-size",
                "label": "KV cache retained · vectors",
                "value": "8"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "History is reused, not removed from attention; persistent storage grows."
              }
            ]
          },
          {
            "id": "decode-e",
            "label": "Decode E",
            "short": "Aha: avoid rebuilding history",
            "sentence": "Uncached K/V rebuilds earlier tokens; Cached K/V reuses their entries and projects only the current token.",
            "why": "For context length L, uncached work is 2L K/V vectors; cached decoding needs two. The Newest query still reads the complete history.",
            "active": [
              "uncached-kv",
              "cached-kv"
            ],
            "calloutRegion": "cached-kv",
            "readouts": [
              {
                "id": "pass-work",
                "label": "K/V vectors this pass · Uncached / Cached",
                "value": "10 / 2"
              },
              {
                "id": "attention-positions",
                "label": "Positions read by Newest query · both paths",
                "value": "5"
              },
              {
                "id": "cache-size",
                "label": "KV cache retained · vectors",
                "value": "10"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Less repeated K/V work, identical continuation, additional storage; these counts are not an overall latency multiplier."
              }
            ]
          }
        ]
      }
    ]
  }
}
